<?php
declare(strict_types=1);
namespace Hostider\Services;
use Hostider\Core\{CanonicalJson,Config,Id};use Hostider\Core\Database\Database;use Hostider\Core\Http\HttpError;use Hostider\Core\Security\{Crypto,Principal};use Hostider\Providers\Contract\Operation;use Hostider\Providers\Mock\DurableCpanel;
final readonly class RenewalWorker
{
    public function __construct(private Database $db,private Config $config){}
    public function once(string $id,Principal $actor,string $scenario='SUCCESS'): bool
    {
        if($this->config->environment!=='test'||$actor->impersonating){throw new HttpError(403,'F3_TEST_ONLY');}$repository=new Repository($this->db,$this->config);$trace=Id::uuid();
        $claim=$this->db->transaction(function()use($id,$repository,$actor,$trace): ?array{
            $identity=$this->db->execute("SELECT * FROM svc_operations WHERE id=? AND kind='RENEW'",[$id])->fetch();if(!$identity){return null;}$service=$repository->find($identity['service_id']);$op=$this->db->execute('SELECT * FROM svc_operations WHERE id=? FOR UPDATE',[$id])->fetch();if($op['status']!=='PENDING'){return null;}
            if($service['current_operation_id']!==$id||!in_array($service['status'],['ACTIVE','SUSPENDED'],true)){throw new HttpError(409,'SERVICE_RENEWAL_CONFLICT');}
            $paid=$this->db->execute('SELECT b.status,b.refund_status FROM svc_renewals r JOIN orders o ON o.id=r.order_id JOIN billing_request_states b ON b.request_id=o.payment_request_id WHERE r.operation_id=? AND r.customer_id=? AND o.refund_status=\'NONE\' AND o.status<>\'CANCELLED\' FOR UPDATE',[$id,$service['customer_id']])->fetch();if(!$paid||$paid['status']!=='PAID'||$paid['refund_status']!=='NONE'){throw new HttpError(409,'FULL_RENEWAL_PAYMENT_REQUIRED');}
            $provider=$this->db->execute('SELECT * FROM svc_provider_operations WHERE lifecycle_operation_id=? FOR UPDATE',[$id])->fetch();$key=base64_decode($this->config->key,true);$json=(new Crypto($key))->decrypt($provider['request_encrypted'],'svc-operation:'.$provider['id']);if(!hash_equals($provider['request_fingerprint'],hash_hmac('sha256',$json,$key))){throw new HttpError(409,'RENEWAL_REQUEST_INTEGRITY');}$request=json_decode($json,true,32,JSON_THROW_ON_ERROR);$token=Id::uuid();
            $this->db->execute("UPDATE svc_operations SET status='RUNNING',lease_token=?,lease_until=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 60 SECOND),updated_at=UTC_TIMESTAMP(6) WHERE id=?",[$token,$id]);$this->db->execute("UPDATE svc_provider_operations SET status='RUNNING' WHERE lifecycle_operation_id=?",[$id]);$this->db->execute("INSERT INTO svc_attempt_events(operation_id,lease_token,kind,safe_code) VALUES (?,?,'STARTED','RENEWAL_DISPATCH_CLAIMED')",[$id,$token]);$repository->event($service,'RENEWAL_PROVIDER_STARTED',$actor,$trace);return compact('provider','request','token');
        });if(!$claim){return false;}
        try{
            $request=$claim['request'];$provider=$claim['provider'];$adapter=new DurableCpanel($this->db,$this->config,$provider['server_id'],$scenario);$result=$adapter->renewAccount(new Operation($provider['id'],'renewAccount',$request['resource_id'],['expected_end'=>$request['expected_end'],'cycle'=>$request['cycle']]));$proof=null;
            if($result->status==='SUCCESS'&&$result->externalResourceId!==null){$inspect=$adapter->inspectAccount(new Operation(Id::uuid(),'inspectAccount',$result->externalResourceId));if($inspect->status==='SUCCESS'){$proof=$adapter->evidence($result->externalResourceId);}}
            if($result->status==='UNKNOWN'){(new Engine($this->db,$this->config))->markUnknown($id,$claim['token'],$actor,$trace);return true;}
            $this->db->transaction(function()use($id,$claim,$request,$provider,$result,$proof,$repository,$actor,$trace): void{
                $service=$repository->find($request['service_id']);$op=$this->db->execute('SELECT *,lease_until>UTC_TIMESTAMP(6) AS live FROM svc_operations WHERE id=? FOR UPDATE',[$id])->fetch();if($op['status']!=='RUNNING'||!$op['live']||!hash_equals($op['lease_token'],$claim['token'])||$service['current_operation_id']!==$id){throw new HttpError(409,'STALE_SERVICE_LEASE');}
                $renewal=$this->db->execute('SELECT * FROM svc_renewals WHERE id=? FOR UPDATE',[$request['renewal_id']])->fetch();$period=$this->db->execute('SELECT * FROM svc_periods WHERE id=? FOR UPDATE',[$request['period_id']])->fetch();$previous=$this->db->execute('SELECT * FROM svc_periods WHERE id=?',[$request['previous_period_id']])->fetch();$end=\Hostider\Catalog\BillingCycle::next(new \DateTimeImmutable($request['expected_end'],new \DateTimeZone('UTC')),$request['cycle']['kind'],(int)$request['cycle']['interval_count'])->format('Y-m-d H:i:s.u');
                $paid=$this->db->execute('SELECT b.status,b.refund_status FROM orders o JOIN billing_request_states b ON b.request_id=o.payment_request_id WHERE o.id=? AND o.customer_id=? AND o.refund_status=\'NONE\' AND o.status<>\'CANCELLED\' FOR UPDATE',[$renewal['order_id'],$service['customer_id']])->fetch();if(!$paid||$paid['status']!=='PAID'||$paid['refund_status']!=='NONE'){throw new HttpError(409,'RENEWAL_PAYMENT_CHANGED');}
                $success=$result->status==='SUCCESS';if($result->operationId!==$provider['id']||$result->environment!=='mock'||$result->provider!=='cpanel'){throw new HttpError(409,'RENEWAL_RESULT_BINDING');}if($success&&(!$proof||$proof['id']!==$request['resource_id']||$proof['server_id']!==$provider['server_id']||$proof['service_id']!==$service['id']||$proof['ends_at']!==$end||$previous['ends_at']!==$request['expected_end']||$service['current_period_id']!==$previous['id']||!in_array($proof['status'],['ACTIVE','SUSPENDED'],true))){throw new HttpError(409,'RENEWAL_INSPECT_MISMATCH');}
                if($success){$key=base64_decode($this->config->key,true);$json=CanonicalJson::encode($proof);$evidence=Id::uuid();$this->db->execute('INSERT INTO svc_period_evidence(id,period_id,operation_id,evidence_encrypted,fingerprint) VALUES (?,?,?,?,?)',[$evidence,$period['id'],$id,(new Crypto($key))->encrypt($json,'svc-evidence:'.$evidence),hash_hmac('sha256',$json,$key)]);$this->db->execute("UPDATE svc_periods SET starts_at=?,ends_at=?,status='VERIFIED',version=version+1 WHERE id=?",[$request['expected_end'],$end,$period['id']]);$this->db->execute('UPDATE svc_services SET current_period_id=? WHERE id=?',[$period['id'],$service['id']]);}
                else{$this->db->execute("UPDATE svc_periods SET status='FAILED',version=version+1 WHERE id=?",[$period['id']]);}
                $state=$success?'SUCCEEDED':'FAILED';$this->db->execute('UPDATE svc_operations SET status=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?',[$state,$id]);$this->db->execute('UPDATE svc_provider_operations SET status=? WHERE id=?',[$state,$provider['id']]);$this->db->execute('UPDATE svc_renewals SET status=? WHERE id=?',[$success?'VERIFIED':'FAILED',$renewal['id']]);$this->db->execute('UPDATE svc_services SET current_operation_id=NULL,version=version+1 WHERE id=?',[$service['id']]);$this->db->execute("INSERT INTO svc_attempt_events(operation_id,lease_token,kind,safe_code) VALUES (?,?,'FINISHED',?)",[$id,$claim['token'],$success?'RENEWAL_INSPECT_VERIFIED':'RENEWAL_DEFINITIVE_FAILURE']);$repository->event($service,$success?'RENEWAL_VERIFIED':'RENEWAL_FAILED',$actor,$trace);
            });
        }catch(\Throwable $e){try{(new Engine($this->db,$this->config))->markUnknown($id,$claim['token'],$actor,$trace);}catch(\Throwable){}throw $e;}return true;
    }
}
